parameters.jsCode:
// Merged: editorial schedule + source collection + breaking news + duplicate check

const TZ = 'America/New_York';
const contentType = 'linkedin_post';
function tableRows(nodeName, keys) {
  return $(nodeName).all()
    .map((i) => i.json)
    .filter((r) => keys.some((k) => r[k] != null && String(r[k]).trim() !== ''));
}

const historyRows = tableRows('Load Editorial History', ['date', 'category', 'headline', 'topic']);
const draftRows = tableRows('Load Queued Drafts', ['date', 'message', 'headline', 'topic']);

const WEEKLY = {
  1: { category: 'tech_news', label: "Today's Tech News", focus: 'biggest engineering or technology story', examples: ['AI', 'Open Source', 'Cloud', 'Microsoft', 'Google', 'Apple', 'GitHub', 'Vercel', 'Docker'] },
  2: { category: 'software_engineering', label: 'Software Engineering', focus: 'architecture, patterns, and craft', examples: ['Architecture', 'Design Patterns', 'Performance', 'Testing', 'TypeScript', 'React', 'Next.js'] },
  3: { category: 'ai', label: 'AI', focus: 'LLMs, tooling, and agentic workflows', examples: ['LLMs', 'AI tooling', 'Agentic workflows', 'MCP', 'Prompt Engineering', 'Automation', 'AI development'] },
  4: { category: 'deep_dive', label: 'Engineering Deep Dive', focus: 'long-form educational technical post', examples: ['System Design', 'Scalability', 'Docker', 'Kubernetes', 'PostgreSQL', 'Redis', 'Event Driven Architecture'], longForm: true },
  5: { category: 'weekly_roundup', label: 'Weekly Roundup', focus: 'summarize the week', examples: ['weekly technology roundup'] },
  6: { category: 'career', label: 'Career / Productivity', focus: 'leadership, productivity, and engineering culture', examples: ['Leadership', 'Developer productivity', 'Remote work', 'Interview advice', 'Lessons learned', 'Engineering culture'] },
  0: { category: 'evergreen', label: 'Evergreen', focus: 'best practices, tutorials, and timeless lessons', examples: ['Best practices', 'Tutorials', 'Coding tips', 'Architecture diagrams', 'Historical technology lessons'] },
};

const FALLBACK_TOPICS = ['engineering best practice', 'architecture lesson', 'React tip', 'Next.js optimization', 'TypeScript insight', 'Docker workflow', 'PostgreSQL tip', 'AI automation tutorial'];
const BREAKING_ENTITIES = ['openai', 'anthropic', 'google', 'apple', 'microsoft', 'github', 'docker', 'vercel', 'react', 'next.js', 'nextjs', 'typescript', 'cloudflare', 'aws', 'meta', 'nvidia'];
const BREAKING_SIGNALS = ['launch', 'released', 'announces', 'announcement', 'breaking', 'unveils', 'introduces', 'acquires', 'acquisition', 'outage', 'breach'];

const UA = 'Mozilla/5.0 (compatible; IntraWebSocialBot/1.0; +https://intrawebtech.com)';
const SOURCE_WEIGHTS = { 'hacker-news': 10, 'github-trending': 9, 'product-hunt': 8, reddit: 7 };
const KEYWORDS = ['ai', 'software', 'engineering', 'developer', 'cloud', 'security', 'database', 'frontend', 'backend', 'devops', 'open source', 'startup', 'architecture', 'programming', 'api', 'kubernetes', 'typescript', 'python', 'react', 'llm'];

function todayEt() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
}
function dayOfWeekEt() {
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: TZ, weekday: 'short' }).formatToParts(new Date());
  const map = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return map[parts.find((p) => p.type === 'weekday')?.value || 'Mon'] ?? 1;
}
function daysBetween(a, b) {
  const da = Date.parse(a); const db = Date.parse(b);
  if (!da || !db) return 999;
  return Math.abs(da - db) / 86400000;
}
function normalizeTitle(text) { return String(text || '').toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim(); }
function tokenize(text) { return new Set(normalizeTitle(text).split(' ').filter((w) => w.length > 3)); }
function jaccard(a, b) {
  const A = tokenize(a); const B = tokenize(b);
  if (!A.size || !B.size) return 0;
  let inter = 0; for (const t of A) if (B.has(t)) inter += 1;
  return inter / (A.size + B.size - inter);
}
function cleanUrl(url) {
  try { const u = new URL(String(url || '').trim()); return `${u.hostname}${u.pathname}`.toLowerCase().replace(/\/$/, ''); }
  catch { return normalizeTitle(url); }
}

async function fetchText(url) {
  try {
    const body = await this.helpers.httpRequest({ method: 'GET', url, headers: { 'User-Agent': UA, Accept: 'application/rss+xml, application/xml, text/xml, */*' }, timeout: 30000 });
    const text = typeof body === 'string' ? body : JSON.stringify(body);
    if (/502 Bad Gateway|<title>502/i.test(text)) return '';
    return text;
  } catch { return ''; }
}
async function fetchHnStories() {
  for (const url of ['https://news.ycombinator.com/rss', 'https://hnrss.org/best?count=30']) {
    const xml = await fetchText.call(this, url);
    if (xml && /<item/i.test(xml)) return { xml, status: 'ok', via: url };
  }
  try {
    const ids = await this.helpers.httpRequest({ method: 'GET', url: 'https://hacker-news.firebaseio.com/v0/topstories.json', json: true, timeout: 30000 });
    const stories = [];
    for (const id of (ids || []).slice(0, 20)) {
      try {
        const item = await this.helpers.httpRequest({ method: 'GET', url: `https://hacker-news.firebaseio.com/v0/item/${id}.json`, json: true, timeout: 15000 });
        if (item?.title && item?.url) stories.push({ title: item.title, link: item.url, summary: '', source: 'hacker-news', publishedAt: new Date((item.time || Date.now() / 1000) * 1000).toISOString() });
      } catch {}
    }
    if (stories.length) return { stories, status: 'ok', via: 'firebase-api' };
  } catch {}
  return { xml: '', stories: [], status: 'failed', via: 'none' };
}
function parseRss(xml, source) {
  if (!xml || typeof xml !== 'string') return [];
  const blocks = xml.match(/<(?:item|entry)[\s\S]*?<\/(?:item|entry)>/gi) || [];
  const stories = [];
  for (const block of blocks) {
    const titleMatch = block.match(/<title[^>]*>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/i);
    const linkMatch = block.match(/<link[^>]*href="([^"]+)"/i) || block.match(/<link[^>]*>([\s\S]*?)<\/link>/i);
    const descMatch = block.match(/<(?:description|summary|content)[^>]*>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/(?:description|summary|content)>/i);
    const dateMatch = block.match(/<(?:pubDate|updated|published)[^>]*>([\s\S]*?)<\/(?:pubDate|updated|published)>/i);
    const title = (titleMatch?.[1] || '').replace(/<[^>]*>/g, '').trim();
    const link = (linkMatch?.[1] || '').replace(/<[^>]*>/g, '').trim();
    const summary = (descMatch?.[1] || '').replace(/<[^>]*>/g, '').trim().slice(0, 400);
    const publishedAt = dateMatch ? new Date(dateMatch[1].trim()) : new Date();
    if (!title || !link || !/^https?:\/\//i.test(link)) continue;
    stories.push({ title, link, summary, source, publishedAt: publishedAt.toISOString() });
  }
  return stories;
}

// --- Schedule ---
const dow = dayOfWeekEt();
const scheduled = WEEKLY[dow] || WEEKLY[1];
const recentCats = historyRows.filter((r) => r.published === true || r.published === 'true').map((r) => ({ category: r.category, daysAgo: daysBetween(todayEt(), r.date) }));
const tooRecent = new Set(recentCats.filter((r) => r.daysAgo < 14).map((r) => r.category));
let category = scheduled.category;
if (tooRecent.has(category)) {
  const alt = Object.values(WEEKLY).map((w) => w.category).find((c) => !tooRecent.has(c));
  if (alt) category = alt;
}
const schedule = Object.values(WEEKLY).find((w) => w.category === category) || scheduled;
const fallbackTopic = FALLBACK_TOPICS[Math.floor(Math.random() * FALLBACK_TOPICS.length)];

// --- Collect sources ---
const fetchStatus = {};
const all = [];
const hn = await fetchHnStories.call(this);
fetchStatus['hacker-news'] = hn.status;
if (hn.stories?.length) all.push(...hn.stories); else all.push(...parseRss(hn.xml, 'hacker-news'));
for (const [key, url] of [['github-trending', 'https://mshibanami.github.io/GitHubTrendingRSS/daily/all.xml'], ['reddit', 'https://www.reddit.com/r/programming+devops+technology/hot/.rss?limit=25'], ['product-hunt', 'https://www.producthunt.com/feed']]) {
  const xml = await fetchText.call(this, url);
  fetchStatus[key] = xml ? 'ok' : 'failed';
  all.push(...parseRss(xml, key));
}
const seen = new Set();
const now = Date.now();
function scoreStory(story) {
  let score = SOURCE_WEIGHTS[story.source] || 5;
  const ageHours = (now - new Date(story.publishedAt).getTime()) / 3600000;
  if (ageHours <= 24) score += 8; else if (ageHours <= 48) score += 4;
  const haystack = `${story.title} ${story.summary}`.toLowerCase();
  for (const keyword of KEYWORDS) if (haystack.includes(keyword)) score += 1.5;
  return Math.round(score * 10) / 10;
}
const topStories = [];
for (const story of all) {
  const key = `${normalizeTitle(story.title)}|${story.link}`;
  if (seen.has(key)) continue;
  seen.add(key);
  topStories.push({ ...story, score: scoreStory(story) });
}
topStories.sort((a, b) => b.score - a.score);

// --- Breaking news ---
function scoreBreaking(story) {
  const hay = `${story.title} ${story.summary}`.toLowerCase();
  let score = Number(story.score) || 0;
  for (const e of BREAKING_ENTITIES) if (hay.includes(e)) score += 12;
  for (const s of BREAKING_SIGNALS) if (hay.includes(s)) score += 6;
  const ageHours = (now - new Date(story.publishedAt).getTime()) / 3600000;
  if (ageHours <= 12) score += 10; else if (ageHours <= 24) score += 5;
  return score;
}
const ranked = topStories.map((s) => ({ ...s, breakingScore: scoreBreaking(s) })).sort((a, b) => b.breakingScore - a.breakingScore);
const breakingTop = ranked[0];
let categoryLabel = schedule.label;
let topic = `${schedule.label}: ${schedule.examples[Math.floor(Math.random() * schedule.examples.length)]}`;
let breakingNewsOverride = false;
if (breakingTop && breakingTop.breakingScore >= 28) {
  category = 'tech_news';
  categoryLabel = 'Breaking Tech News';
  topic = breakingTop.title;
  breakingNewsOverride = true;
}

// --- Duplicate check ---
const seenTitles = new Set();
const seenUrls = new Set();
for (const row of [...historyRows, ...draftRows]) {
  if (row.headline) seenTitles.add(normalizeTitle(row.headline));
  if (row.topic) seenTitles.add(normalizeTitle(row.topic));
  if (row.url) seenUrls.add(cleanUrl(row.url));
  if (row.primary_url) seenUrls.add(cleanUrl(row.primary_url));
}
let selectedStory = breakingNewsOverride ? breakingTop : ranked[0];
let skipRun = false;
let skipReason = '';
if (selectedStory) {
  const titleKey = normalizeTitle(selectedStory.title);
  const urlKey = cleanUrl(selectedStory.link);
  if (seenUrls.has(urlKey)) { skipRun = true; skipReason = `URL already used: ${selectedStory.link}`; }
  else {
    for (const t of seenTitles) {
      if (jaccard(t, titleKey) >= 0.72) { skipRun = true; skipReason = `Headline too similar: ${selectedStory.title}`; break; }
    }
  }
}
if (!skipRun && !selectedStory) {
  topic = fallbackTopic;
  selectedStory = null;
}

if (!skipRun && !topStories.length) {
  skipRun = true;
  skipReason = `All source fetches failed: ${JSON.stringify(fetchStatus)}`;
}

return [{ json: {
  contentType,
  postType: 'primary',
  category,
  categoryLabel,
  categoryFocus: schedule.focus,
  topic: selectedStory?.title || topic,
  fallbackTopic,
  longForm: schedule.longForm === true,
  skipResearch: ['evergreen', 'career', 'deep_dive'].includes(category),
  breakingNewsOverride,
  selectedStory,
  topStories: ranked.slice(0, 12),
  storyCount: ranked.length,
  skipRun,
  skipReason,
  editorialDate: todayEt(),
  pickedAt: new Date().toISOString(),
} }];

function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

const upstream = $input.first().json;
const collected = safeNode('Editorial Planner');
const topicData = collected;

const topic = collected?.topic || topicData?.topic || upstream.topic || 'Breaking Tech News';
const postType = collected?.postType || topicData?.postType || upstream.postType || 'primary';
const pipelineSlot = collected?.pipelineSlot || topicData?.pipelineSlot || upstream.pipelineSlot || 'publish';
const publishNow = collected?.publishNow ?? topicData?.publishNow ?? upstream.publishNow ?? false;

let researchText = '';
if (typeof upstream.message === 'string') researchText = upstream.message;
else if (typeof upstream.content === 'string') researchText = upstream.content;
else researchText = JSON.stringify(upstream, null, 2);
researchText = researchText.replace(/\r/g, '');

const rawCitations = Array.isArray(upstream.citations)
  ? upstream.citations.filter((url) => typeof url === 'string' && /^https?:\/\//i.test(url))
  : [];

function cleanUrl(url) { return (url || '').trim().replace(/[.,;:!?\)\]]+$/, ''); }
function urlScore(url) {
  try {
    const pathParts = new URL(url).pathname.split('/').filter(Boolean);
    if (/youtube\.com|youtu\.be|vimeo\.com/i.test(url)) return 100;
    if (pathParts.length >= 3) return 85;
    if (pathParts.length >= 1) return 55;
    return 5;
  } catch { return 0; }
}
function isArticleUrl(url) { return urlScore(cleanUrl(url)) >= 50; }
function pickPrimaryUrl(urls) {
  const unique = [...new Set(urls.map(cleanUrl).filter(Boolean))];
  return unique.sort((a, b) => urlScore(b) - urlScore(a)).find(isArticleUrl) || unique[0] || '';
}
function extractUrls(text) { return (text.match(/https?:\/\/[^\s\)\]"'<>]+/gi) || []).map(cleanUrl); }
function extractSourceUrls(text) {
  return [...new Set([...text.matchAll(/^Source URL:\s*(.+)$/gim)].flatMap((m) => extractUrls(m[1])))];
}
function splitStoryBlocks(text) {
  return text.split(/(?:^|\n)---+(?:\n|$)/).map((b) => b.replace(/^---+\s*/m, '').trim()).filter((b) => /STORY\s+\d+/i.test(b));
}
function resolveCitationRefs(text, citationList) {
  return text.replace(/Source URL:\s*\[(\d+)\]/gi, (_, n) => {
    const url = citationList[Number(n) - 1] || citationList[Number(n)] || citationList[0];
    return url && /^https?:\/\//i.test(url) ? `Source URL: ${url}` : `Source URL: ${url || `[${n}]`}`;
  });
}

researchText = resolveCitationRefs(researchText, rawCitations);
const sourceUrlsFromText = extractSourceUrls(researchText);
const citations = [...new Set([...sourceUrlsFromText.filter(isArticleUrl), ...rawCitations.filter(isArticleUrl)])];
let storyBlocks = splitStoryBlocks(researchText);
if (!storyBlocks.length && citations.length) {
  storyBlocks = citations.map((url, i) => `### STORY ${i + 1}\nTitle: Story ${i + 1}\nSource URL: ${url}`);
}

const stories = storyBlocks.map((block, index) => {
  const storyIndex = Number((block.match(/STORY\s+(\d+)/i) || [])[1]) || index + 1;
  const titleMatch = block.match(/Title:\s*(.+)/i);
  const title = (titleMatch?.[1] || `Story ${storyIndex}`).replace(/^\*+|\*+$/g, '').trim();
  const blockUrls = [...extractSourceUrls(block), ...extractUrls(block)];
  const fallbackUrls = blockUrls.length ? blockUrls : [citations[storyIndex - 1], citations[index], citations[0]].filter(Boolean);
  return { index: storyIndex, title, primaryUrl: pickPrimaryUrl(fallbackUrls), sourceUrls: blockUrls.filter(isArticleUrl) };
}).filter((s) => s.primaryUrl).sort((a, b) => a.index - b.index);

const storyCatalog = stories.length
  ? stories.map((s) => `${s.index}. ${s.title}\n   Source: ${s.primaryUrl}`).join('\n')
  : citations.map((url, i) => `${i + 1}. Source: ${url}`).join('\n');

return [{ json: { topic, postType, pipelineSlot, publishNow, stories, citations, sourceUrlsFromText, storyCatalog, researchText: `${researchText}\n\n## Story catalog:\n${storyCatalog}` } }];

// Merged: select best draft + parse JSON + validate quality + first comment

function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

function extractJsonObject(rawText) {
  if (!rawText || typeof rawText !== 'string') return null;
  const cleaned = rawText.replace(/^```json\s*|```\s*$/g, '').trim();
  try { return JSON.parse(cleaned); } catch {}
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) return null;
  try { return JSON.parse(match[0]); } catch { return null; }
}

function writerText(writer) {
  if (!writer || typeof writer !== 'object') return '';
  if (typeof writer.text === 'string') return writer.text;
  if (Array.isArray(writer.content)) {
    return writer.content.find((c) => c.type === 'text')?.text || writer.content.map((c) => c.text || '').join('\n');
  }
  return '';
}

const planner = safeNode('Editorial Planner') || {};
const research = safeNode('Format Research') || {};
const stories = research.stories || [];
const citations = research.citations || [];
const sourceUrlsFromText = research.sourceUrlsFromText || [];
const writerItem = $('AI Writer').first()?.json || {};

let parsed = extractJsonObject(writerText(writerItem));
if (!parsed) parsed = {};

const draft = {
  headline: parsed.headline || '',
  message: parsed.message || '',
  short_message: parsed.short_message || '',
  story_index: Number(parsed.story_index) || 1,
};

function cleanUrl(url) { return (url || '').trim().replace(/[.,;:!?\)\]]+$/, ''); }
function isValidUrl(url) { return typeof url === 'string' && /^https?:\/\//i.test(cleanUrl(url)); }
function extractSourceUrls(blockText) {
  return [...blockText.matchAll(/^Source URL:\s*(https?:\/\/[^\s\)\]"'<>]+)/gim)].map((m) => cleanUrl(m[1]));
}
function splitStoryBlocks(blockText) {
  return blockText.replace(/\r/g, '').split(/(?:^|\n)---+(?:\n|$)/).map((b) => b.trim()).filter((b) => /STORY\s+\d+/i.test(b));
}
function urlForStoryIndex(storyIndex) {
  const story = stories.find((s) => s.index === storyIndex);
  if (story?.primaryUrl && isValidUrl(story.primaryUrl)) return story.primaryUrl;
  const blocks = splitStoryBlocks(research.researchText || '');
  const block = blocks.find((b) => new RegExp(`STORY\\s+${storyIndex}`, 'i').test(b)) || blocks[storyIndex - 1] || blocks[0];
  if (block) { const urls = extractSourceUrls(block); if (isValidUrl(urls[0])) return urls[0]; }
  const top = planner.topStories || [];
  if (isValidUrl(top[storyIndex - 1]?.link)) return top[storyIndex - 1].link;
  if (isValidUrl(planner.selectedStory?.link)) return planner.selectedStory.link;
  for (const url of [citations[storyIndex - 1], citations[0], sourceUrlsFromText[0]]) {
    if (isValidUrl(url)) return url;
  }
  return '';
}
function stripUrls(input) {
  return (input || '').replace(/https?:\/\/[^\s\)\]"'<>]+/gi, '').replace(/\n{3,}/g, '\n\n').trim();
}

function buildFirstComment(primaryUrl, body) {
  const lines = [];
  if (primaryUrl) lines.push(primaryUrl);
  const questionMatch = body.match(/([^\n?]*\?)\s*$/);
  const hook = questionMatch
    ? questionMatch[1].trim()
    : 'What stood out to you in this story?';
  if (hook && (!lines.length || !lines.join('\n').includes(hook))) {
    if (lines.length) lines.push('');
    lines.push(hook);
  }
  return lines.join('\n').trim();
}

const storyIndex = Number(draft.story_index) || 1;
const primaryUrl = urlForStoryIndex(storyIndex);
const rawMessage = draft.message || draft.short_message || '';
const message = stripUrls(rawMessage);
const shortMessage = stripUrls(draft.short_message || draft.message || '');
const firstComment = buildFirstComment(primaryUrl, rawMessage);

let validPost = true;
let invalidReason = '';
const msg = String(message || '').trim();
if (!draft.headline || !msg || msg.startsWith('{') || msg.length < 80) {
  validPost = false;
  invalidReason = 'Draft failed quality check: missing headline or substantive message';
}

return [{ json: {
  headline: draft.headline || '',
  message,
  short_message: shortMessage,
  firstComment,
  topic: planner.topic || research.topic || '',
  category: planner.category,
  categoryLabel: planner.categoryLabel,
  contentType: planner.contentType || 'linkedin_post',
  story_index: storyIndex,
  story_title: stories.find((s) => s.index === storyIndex)?.title || planner.selectedStory?.title || '',
  primaryUrl,
  validPost,
  invalidReason,
} }];

values.content:
=You are an expert visual prompt engineer for LinkedIn social posts.

Write ONE detailed image-generation prompt based on the post below. The image must be professional, modern, and visually compelling. Do not include any text, logos, watermarks, or UI chrome in the image.

Headline: {{ $('Prepare Post').item.json.headline }}

Post:
{{ $('Prepare Post').item.json.message }}

Return ONLY the image prompt text. No JSON, no markdown, no explanation.

parameters.jsCode:
function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

const channels = $('Postiz - Get Channels').all().map((item) => item.json);
const upload = safeNode('Postiz - Upload') || {};
const post = safeNode('Prepare Post') || {};

const limits = {
  threads: 500, bluesky: 300, linkedin: 3000, 'linkedin-page': 3000,
  x: 280, twitter: 280, facebook: 63206, instagram: 2200, 'instagram-standalone': 2200,
};

const COMMENT_DELAY_MS = {
  x: 120000, twitter: 120000, threads: 120000, bluesky: 120000,
  linkedin: 120000, 'linkedin-page': 120000,
  instagram: 120000, 'instagram-standalone': 120000,
  facebook: 120000, reddit: 120000, default: 120000,
};

function stripUrls(text) {
  return (text || '').replace(/https?:\/\/[^\s\)\]"'<>]+/gi, '').replace(/\n{3,}/g, '\n\n').trim();
}

function trimTo(text, max) {
  if (!max || text.length <= max) return text;
  return `${text.slice(0, max - 3)}...`;
}

function contentForPlatform(platform, long, short) {
  const useShort = ['threads', 'bluesky', 'x', 'twitter'].includes(platform);
  const body = useShort ? (short || long) : (long || short);
  return trimTo(body, limits[platform]);
}

function commentForPlatform(platform, comment) {
  if (!comment) return '';
  return trimTo(comment, limits[platform]);
}

function platformSettings(platform) {
  const settings = { __type: platform };
  if (platform === 'instagram' || platform === 'instagram-standalone') settings.post_type = 'post';
  if (platform === 'facebook') settings.post_type = 'post';
  return settings;
}

const headline = String(post.headline || '').trim();
const mainBody = stripUrls(post.message || post.short_message || '');
const shortBody = stripUrls(post.short_message || post.message || '');
const longMain = headline ? `${headline}\n\n${mainBody}` : mainBody;
const shortMain = headline ? `${headline}\n\n${shortBody}` : shortBody;

const firstComment = String(post.firstComment || '').trim();
const imageAttachment = upload?.id && upload?.path ? [{ id: upload.id, path: upload.path }] : [];

const posts = channels.filter((c) => !c.disabled).map((channel) => {
  const platform = channel.identifier || channel.platform;
  const mainContent = contentForPlatform(platform, longMain, shortMain);
  const value = [{ content: mainContent, id: '', image: imageAttachment }];

  const commentText = commentForPlatform(platform, firstComment);
  if (commentText) {
    value.push({
      content: commentText,
      id: '',
      image: [],
      delay: COMMENT_DELAY_MS[platform] || COMMENT_DELAY_MS.default,
    });
  }

  return {
    integration: { id: channel.id },
    value,
    group: '',
    settings: platformSettings(platform),
  };
});

return [{ json: {
  type: 'draft',
  shortLink: false,
  date: new Date().toISOString(),
  tags: [{ value: post.category || 'primary' }],
  posts,
  channelCount: posts.length,
  hasFirstComment: !!firstComment,
  publishMode: 'draft',
} }];

function safeNode(name) {
  try { return $(name).first()?.json || null; } catch { return null; }
}

const post = safeNode('Prepare Post') || {};
const TZ = 'America/New_York';
const today = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());

return [{ json: {
  date: today,
  category: post.category || 'tech_news',
  topic: post.topic || '',
  headline: post.headline || '',
  url: post.primaryUrl || '',
  published: false,
} }];
